/// A row of a reference table (its JavaScript fields, camel-cased; `jsonValue` restores the original keys).
public struct RelType: Sendable, Hashable, JSONRepresentable {
  public let code: String
  public let family: String
  public let label: String
  public let inverseLabel: String
  public let directed: Int
  public let requiresPrecedence: Int
  public let impliesTransmission: Int
  public let feedbackCapable: Int
  public let glyph: String
  public let description: String
  public let short: String
  public let brief: Bool

  public init(code: String, family: String, label: String, inverseLabel: String, directed: Int, requiresPrecedence: Int, impliesTransmission: Int, feedbackCapable: Int, glyph: String, description: String, short: String, brief: Bool) {
    self.code = code
    self.family = family
    self.label = label
    self.inverseLabel = inverseLabel
    self.directed = directed
    self.requiresPrecedence = requiresPrecedence
    self.impliesTransmission = impliesTransmission
    self.feedbackCapable = feedbackCapable
    self.glyph = glyph
    self.description = description
    self.short = short
    self.brief = brief
  }

  /// The row as the reference's JSON object.
  public var jsonValue: JSONValue {
    let o: JSONObject = ["code": code.jsonValue, "family": family.jsonValue, "label": label.jsonValue, "inverse_label": inverseLabel.jsonValue, "directed": directed.jsonValue, "requires_precedence": requiresPrecedence.jsonValue, "implies_transmission": impliesTransmission.jsonValue, "feedback_capable": feedbackCapable.jsonValue, "glyph": glyph.jsonValue, "description": description.jsonValue, "short": short.jsonValue, "brief": brief.jsonValue]
    return .object(o)
  }
}

